package com.alsafa.native4.core;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.alsafa.native4.sync.SyncOperation;
import org.json.JSONObject;
import java.util.UUID;

/** Transactional AlSafa core writes: business row + durable outbox command commit together. */
public final class CoreStore {
 public interface DbProvider { SQLiteDatabase db(); void enqueue(SQLiteDatabase db, SyncOperation op); }
 private final DbProvider provider; private final String deviceId;
 public CoreStore(DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String createProduct(String name,String ref,String barcode,String brand,int qty,double salePrice,double costPrice,String currency)throws Exception{
  String n=safe(name,140,"اسم المنتج"); if(qty<0||!Double.isFinite(salePrice)||!Double.isFinite(costPrice)||salePrice<0||costPrice<0)throw new IllegalArgumentException("الكمية أو السعر غير صالح"); long now=System.currentTimeMillis();String id="product-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("product_id",id);v.put("name",n);v.put("ref",trim(ref));v.put("barcode",trim(barcode));v.put("brand",trim(brand));v.put("quantity",qty);v.put("sale_price",salePrice);v.put("cost_price",costPrice);v.put("currency",money(currency));v.put("created_at",now);v.put("updated_at",now);db.insertOrThrow("products",null,v);JSONObject p=new JSONObject().put("productId",id).put("name",n).put("ref",trim(ref)).put("barcode",trim(barcode)).put("brand",trim(brand)).put("quantity",qty).put("salePrice",salePrice).put("costPrice",costPrice).put("currency",money(currency)).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.PRODUCT_CREATE,id,p.toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public String recordSale(String productId,int qty,String payment,String currency)throws Exception{return recordSaleInternal(productId,qty,payment,currency,null);}
 public String recordSaleWithPayments(String productId,int qty,String currency,org.json.JSONArray payments)throws Exception{return recordSaleInternal(productId,qty,"SPLIT",currency,payments);}
 private String recordSaleInternal(String productId,int qty,String payment,String currency,org.json.JSONArray payments)throws Exception{
  if(qty<=0)throw new IllegalArgumentException("الكمية يجب أن تكون أكبر من صفر");money(currency);if(payments==null)payment(payment);else{if(payments.length()==0||payments.length()>100)throw new IllegalArgumentException("قائمة الدفعات غير صالحة");for(int i=0;i<payments.length();i++){JSONObject line=payments.getJSONObject(i);double amount=line.optDouble("amount",Double.NaN);if(!Double.isFinite(amount)||amount<=0||amount>1000000000000d)throw new IllegalArgumentException("مبلغ الدفعة غير صالح");String lineCurrency=money(line.optString("currency"));if(!lineCurrency.equals(money(currency)))throw new IllegalArgumentException("تعدد العملات يتطلب سعر صرف موثقًا؛ يمكن تقسيم الدفع بوسائل مختلفة ضمن العملة نفسها");String method=payment(line.optString("paymentMethod",line.optString("method")));if("LATER".equals(method))throw new IllegalArgumentException("الدفعة المؤجلة ليست تحصيلاً");}}SQLiteDatabase db=provider.db();db.beginTransaction();try{String name,productCurrency;int before;double price,cost;try(Cursor c=db.rawQuery("SELECT name,quantity,sale_price,currency,cost_price FROM products WHERE product_id=? AND deleted_at IS NULL",new String[]{productId})){if(!c.moveToFirst())throw new IllegalArgumentException("المنتج غير موجود");name=c.getString(0);before=c.getInt(1);price=c.getDouble(2);productCurrency=c.getString(3);cost=c.getDouble(4);}if(before<qty)throw new IllegalArgumentException("كمية المخزون غير كافية");if(payments!=null){java.math.BigDecimal paid=java.math.BigDecimal.ZERO;for(int i=0;i<payments.length();i++)paid=paid.add(java.math.BigDecimal.valueOf(payments.getJSONObject(i).getDouble("amount")));java.math.BigDecimal due=java.math.BigDecimal.valueOf(price).multiply(java.math.BigDecimal.valueOf(qty));if(paid.subtract(due).abs().compareTo(new java.math.BigDecimal("0.000001"))>0)throw new IllegalArgumentException("مجموع الدفعات لا يساوي قيمة الفاتورة");}if(!money(currency).equals(money(productCurrency)))throw new IllegalArgumentException("عملة الفاتورة تختلف عن عملة سعر المنتج؛ يلزم تحويل موثق قبل البيع");if(!Double.isFinite(cost)||cost<0)throw new IllegalArgumentException("تكلفة المنتج غير صالحة");if(!Double.isFinite(cost*qty)||!Double.isFinite(price*qty-cost*qty))throw new IllegalArgumentException("حساب الربح غير صالح");if(!Double.isFinite(price)||price<0||!Double.isFinite(price*qty))throw new IllegalArgumentException("سعر البيع غير صالح");long now=System.currentTimeMillis();String invoiceId="sale-"+UUID.randomUUID(),invoiceNo="S-"+now+"-"+invoiceId.substring(invoiceId.length()-8),itemId="item-"+UUID.randomUUID();double total=price*qty;ContentValues inv=new ContentValues();inv.put("invoice_id",invoiceId);inv.put("invoice_no",invoiceNo);inv.put("invoice_type","SALE");inv.put("currency",money(currency));inv.put("subtotal",total);inv.put("total",total);inv.put("payment_method",payments==null?payment(payment):"SPLIT");inv.put("created_at",now);inv.put("updated_at",now);db.insertOrThrow("invoices",null,inv);ContentValues item=new ContentValues();item.put("item_id",itemId);item.put("invoice_id",invoiceId);item.put("product_id",productId);item.put("description",name);item.put("quantity",qty);item.put("unit_price",price);item.put("total",total);item.put("unit_cost_snapshot",cost);item.put("cost_total_snapshot",cost*qty);item.put("profit_snapshot",total-cost*qty);item.put("created_at",now);db.insertOrThrow("invoice_items",null,item);int after=before-qty;ContentValues pv=new ContentValues();pv.put("quantity",after);pv.put("updated_at",now);if(db.update("products",pv,"product_id=? AND quantity>=?",new String[]{productId,String.valueOf(qty)})!=1)throw new IllegalStateException("تعذر تثبيت المخزون");ContentValues sm=new ContentValues();sm.put("move_id","stock-"+UUID.randomUUID());sm.put("product_id",productId);sm.put("source_type","SALE");sm.put("source_id",invoiceId);sm.put("before_qty",before);sm.put("delta_qty",-qty);sm.put("after_qty",after);sm.put("created_at",now);db.insertOrThrow("stock_moves",null,sm);if(payments==null){if(!"LATER".equals(payment(payment))){ContentValues cm=new ContentValues();cm.put("move_id","cash-"+UUID.randomUUID());cm.put("source_type","SALE");cm.put("source_id",invoiceId);cm.put("direction","IN");cm.put("amount",total);cm.put("currency",money(currency));cm.put("payment_method",payment(payment));cm.put("drawer","SHAM_CASH".equals(payment(payment))?"SHAM_CASH":"EXTERNAL".equals(payment(payment))?"EXTERNAL":"MAIN");cm.put("created_at",now);db.insertOrThrow("cash_moves",null,cm);}}else{for(int i=0;i<payments.length();i++){JSONObject line=payments.getJSONObject(i);String method=payment(line.optString("paymentMethod",line.optString("method")));ContentValues cm=new ContentValues();cm.put("move_id","cash-"+UUID.randomUUID());cm.put("source_type","SALE");cm.put("source_id",invoiceId);cm.put("direction","IN");cm.put("amount",line.getDouble("amount"));cm.put("currency",money(line.getString("currency")));cm.put("payment_method",method);cm.put("drawer","SHAM_CASH".equals(method)?"SHAM_CASH":"EXTERNAL".equals(method)?"EXTERNAL":"MAIN");cm.put("created_at",now);db.insertOrThrow("cash_moves",null,cm);}}JSONObject p=new JSONObject().put("invoiceId",invoiceId).put("invoiceNo",invoiceNo).put("productId",productId).put("productName",name).put("quantity",qty).put("unitPrice",price).put("unitCostSnapshot",cost).put("capitalSnapshot",cost*qty).put("profitSnapshot",total-cost*qty).put("subtotal",total).put("total",total).put("currency",money(currency)).put("paymentMethod",payments==null?payment(payment):"SPLIT").put("stockAfter",after).put("updatedAt",now);if(payments!=null){p.put("paymentLines",payments);p.put("paymentStatus","PAID");}else p.put("paymentStatus","LATER".equals(payment(payment))?"UNPAID":"PAID");provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE,invoiceId,p.toString(),deviceId));db.setTransactionSuccessful();return invoiceNo;}finally{db.endTransaction();}}
 private static String safe(String v,int max,String label){String s=trim(v);if(s.isEmpty()||s.length()>max)throw new IllegalArgumentException(label+" غير صالح");return s;}private static String trim(String v){return v==null?"":v.trim();}private static String money(String c){String x=trim(c).toUpperCase(java.util.Locale.ROOT);if(x.equals("USD")||x.equals("TRY")||x.equals("SYP"))return x;throw new IllegalArgumentException("عملة غير مدعومة: "+x);}private static String payment(String p){String x=trim(p).toUpperCase(java.util.Locale.ROOT);if(x.equals("CASH")||x.equals("SHAM_CASH")||x.equals("EXTERNAL")||x.equals("LATER"))return x;throw new IllegalArgumentException("طريقة دفع غير مدعومة: "+x);}
}
